        return SpacetimeDB.Internal.Errno.HOST_CALL_FAILURE;
    }

    private static SpacetimeDB.Internal.Errno UnknownAnonymousViewId(int id)
    {
        SpacetimeDB.Log.Error($"Unknown anonymous view id: {id}");
        return SpacetimeDB.Internal.Errno.HOST_CALL_FAILURE;
    }
}

